import{_ as e,o as i,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-10-25","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-10-25","date":"2023-10-25T00:00:00.000Z","updated":"2023-11-21T00:00:00.000Z","tags":["Ceph","分布式存储","IAM","账户管理","配额管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.md","lastUpdated":1780460162000}'),n={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-10-25.md"};function r(s,t,a,p,_,g){return i(),o("div",null,[...t[0]||(t[0]=[l('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>在 2023 年 10 月 25 日举行的 Ceph RGW 重构会议上，与会人员主要讨论了 IAM（身份和访问管理）的未来发展方向，并探讨了账户设计、所有权、使用会计、配额管理和账户层次结构等相关议题。</p><p><strong>主要议题包括</strong>：</p><ol><li><strong>IAM 的未来方向</strong>：讨论了现有 IAM 系统的不足，并提出了改进建议。</li><li><strong>账户所有权和使用会计</strong>：讨论了如何处理 OIDC 提供者和策略，以及如何归属使用情况。提出了根账户的概念，其中根账户是唯一具有所有权概念的主体。</li><li><strong>账户和用户的统计数据</strong>：讨论了账户级别的统计数据和配额管理，以及如何处理多用户共享资源的情况。</li><li><strong>账户层次结构</strong>：探讨了账户之间的层次关系，以及如何通过组织单位（OU）来管理账户和配额。</li><li><strong>配额管理</strong>：讨论了配额的设置和管理，包括如何在账户级别和用户级别进行配额管理。</li></ol><p><strong>决定事项</strong>：</p><ul><li>所有权的归属将归于根账户，而不是用户。</li><li>使用会计和配额将在账户级别进行管理。</li><li>初步探讨了账户层次结构的可能性，但尚未形成具体决策。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>更新设计文档。</li><li>进一步探讨配额管理。</li><li>研究账户层次结构。</li></ul><p><strong>其他讨论点</strong>：</p><ul><li>用户名和密码与账户恢复相关。</li><li>账户如何将 Swift 用户和 S3 用户整合在一起，以及账户如何管理配额和 IAM 策略。</li></ul><p>会议对 IAM 的未来方向、账户所有权、使用会计、配额管理和账户层次结构进行了深入讨论，并形成了初步的决策和后续行动计划。需要进一步的工作来细化这些决策并实现它们。</p>',11)])])}const f=e(n,[["render",r]]);export{d as __pageData,f as default};
